async function run(){
  const rows=[]; const seen=new Set(); let pages=0;
  const grab=()=>{document.querySelectorAll('table tr').forEach(tr=>{const td=[...tr.querySelectorAll('td')].map(x=>x.innerText.trim()); if(td.length>=8 && /^\d{4}$/.test(td[0])){const k=td.join('|'); if(!seen.has(k)){seen.add(k); rows.push(td.slice(0,8));}}});};
  const pagText=()=>{const m=(document.body.innerText||'').match(/linha\(s\)\s*\d+\s*-\s*\d+\s*de\s*\d+/); return m?m[0]:null;};
  for(let i=0;i<90;i++){
    grab(); pages++;
    const before=pagText();
    const next=[...document.querySelectorAll('a,button,span')].find(e=>((e.innerText||e.textContent||'').trim()==='Próximo'));
    if(!next) break;
    next.click();
    let t=0; while(t<150){await new Promise(r=>setTimeout(r,200)); if(pagText()!==before) break; t++;}
    if(t>=150) return {erro:'timeout', pages, n:rows.length, last:before};
  }
  grab();
  return {pages, n:rows.length, last:pagText(), rows};
}
await run();

